cd /tmp && node -e "
const UA='EasyMA research beckhamwilson@gmail.com';
(async()=>{const r=await fetch('https://data.sec.gov/api/xbrl/companyfacts/CIK0001467858.json',{headers:{'User-Agent':UA}});const f=await r.json();
for(const d of ['2026-06-30','2025-12-31']){console.log('--- GM @'+d);
for(const ns of Object.keys(f.facts)){const b=f.facts[ns];for(const n of Object.keys(b)){
if(!/debt|borrow|notespayable|financelease|linesofcredit/i.test(n))continue;
if(/AvailableForSale|HeldToMaturity|Receivable|RepaymentsOf|ProceedsFrom|InterestExpense/i.test(n))continue;
const u=(b[n].units||{})['USD']||[];const at=u.filter(x=>!x.start&&x.end===d);if(!at.length)continue;
const v=at.reduce((a,x)=>Math.abs(x.val)>Math.abs(a.val)?x:a);
console.log('  '+ns+':'+n+' = '+(v.val/1e6).toFixed(0)+'M form='+v.form);}}}
})();
" 2>&1 | head -40
